/*
*  Header file clock.h    
*/

#pragma once

#include <iostream>
#include <fstream>

class Clock {
public:
    // constructors
    Clock() = default;  // compiler generates the default constructor
    Clock(int h, int m, int s = 0);

    Clock(const Clock& c) = default;
    // use the default copy constructor generated by the compiler -- shallow copy

    // Destructor
    ~Clock() = default;
    // use the default destructor generated by the compiler -- function with empty body

    Clock& operator=(const Clock& C) = default;
    // use the default assignment operator generated by the compiler -- shallow copy

    void display(bool write_sec = true) const;

    void reset();  // resets the clock to 00:00:00

    // To add 1s more to the clock
    void tick();  // does not allow cascading

private:
    // represent time as hh:mm:ss
    int hh{0};  // 0-23
    int mm{0};  // 0-59
    int ss{0};  // 0-59
    // by default the data members are initialized to zero
};
